// Code generated by packages/kit-compose/src/build.ts from src/map.ts + variants/. DO NOT EDIT.

package compose

import "github.com/ui8kit/codegen/generated/templ/ui/text"

// TitleProps: Title: Text + recipe title.
type TitleProps struct {
	Size string
	Weight string
	// As — heading level 1..6 (h1..h6), else h2
	As string
	text.TextProps
}

func titleInner(p TitleProps) text.TextProps {
	in := p.TextProps
	in.Class = Join(Rc("title", map[string]string{"size": p.Size, "weight": p.Weight}), p.TextProps.Class)
	in.Tag = Heading(p.As, "h2")
	return in
}

// Title renders Text with the composition classes.
templ Title(p TitleProps) {
	@text.Text(titleInner(p)) {
		{ children... }
	}
}
